pub fn modelAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "position")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "normal0")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "texcoord0")) {
        return 2;
    }
    return null;
}
pub fn modelTextureSlot(tex_name: []const u8) ?usize {
    if (std.mem.eql(u8, tex_name, "diffuse_texture")) {
        return 0;
    }
    if (std.mem.eql(u8, tex_name, "specular_texture")) {
        return 1;
    }
    return null;
}
pub fn modelSamplerSlot(smp_name: []const u8) ?usize {
    if (std.mem.eql(u8, smp_name, "texture_sampler")) {
        return 0;
    }
    return null;
}
pub fn modelUniformBlockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return 0;
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        return 1;
    }
    return null;
}
pub fn modelUniformBlockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return @sizeOf(VsParams);
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        return @sizeOf(FsParams);
    }
    return null;
}
pub fn modelUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "mvp")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "model")) {
            return 64;
        }
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        if (std.mem.eql(u8, u_name, "light_position")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "view_position")) {
            return 16;
        }
    }
    return null;
}
pub fn modelUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "mvp")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "mvp";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "model")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "model";
            return desc;
        }
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        if (std.mem.eql(u8, u_name, "light_position")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT4;
            desc.array_count = 0;
            desc.glsl_name = "light_position";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "view_position")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT4;
            desc.array_count = 0;
            desc.glsl_name = "view_position";
            return desc;
        }
    }
    return null;
}
